  if(!hit) hit=opts.find(o=>o.textContent.trim().toLowerCase().includes(name.toLowerCase()) && !o.textContent.toLowerCase().includes('strategy') && !o.textContent.toLowerCase().includes('federation') && !o.textContent.toLowerCase().includes('amplify'));
  if(hit){ hit.click(); await sleep(300); return {name, status:'ok', picked:hit.textContent.trim().split('\n')[0].trim(), opts:opts.length}; }
  return {name, status:'miss', opts:opts.length, sample:opts.slice(0,5).map(o=>o.textContent.trim().slice(0,50))};
