async function addSkill(name){
  const input=document.querySelector('input[placeholder*="Enter skills"], [role=searchbox][placeholder*="skills"], input[type=search]');
  // find searchbox
  const box=Array.from(document.querySelectorAll('input')).find(i=>(i.placeholder||'').toLowerCase().includes('skill')) || document.querySelector('[role=searchbox]');
  if(!box) return {err:'no input', name};
  box.focus(); box.click();
  const setter=Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype,'value').set;
  setter.call(box,'');
  box.dispatchEvent(new Event('input',{bubbles:true}));
  await sleep(100);
  // type char by char better via native setter + input
  setter.call(box, name);
  box.dispatchEvent(new Event('input',{bubbles:true}));
  await sleep(900);
  let opts=Array.from(document.querySelectorAll('[role=option], .air3-menu-item, button')).filter(o=>o.offsetParent!==null);
  // Prefer exact skill match buttons near typeahead
  let match=Array.from(document.querySelectorAll('[role=option]')).find(o=>o.textContent.trim().toLowerCase()===name.toLowerCase());
  if(!match) match=Array.from(document.querySelectorAll('[role=option]')).find(o=>o.textContent.trim().toLowerCase().includes(name.toLowerCase()));
  if(!match){
    // try clicking suggestion that equals
    const btns=Array.from(document.querySelectorAll('li, [role=option], .air3-token-container ~ * button'));
    return {err:'no match', name, sample:Array.from(document.querySelectorAll('[role=option]')).slice(0,10).map(o=>o.textContent.trim()), val:box.value};
  }
  match.click(); await sleep(400);
  return {ok:true, name, skills:Array.from(document.querySelectorAll('[class*=token], li')).filter(li=>/Remove .* Tag/.test(li.innerText)).map(li=>li.innerText.replace(/Remove.*$/,'').trim()).slice(0,20)};
}
